parameters.jsCode:
const inputData = $json;
const triggerData = $('When Executed by Another Workflow').first()?.json || {};

// 1. הגנה לתרחישי SKIP
if (
  inputData.decision === 'SKIP' || 
  inputData.status === 'SKIPPED' || 
  inputData.orderType === 'RFQ' || 
  inputData.orderType === 'RFI'
) {
  return [{
    json: {
      ...inputData,
      status: 'SKIPPED',
      decision: 'SKIP',
      nextAction: 'LOGISTICS_SKIP'
    }
  }];
}

// 2. חילוץ ה-JSON שהגיע מסוכן ה-LLM
let parsedData = {};
let responseText = inputData.output || inputData.response || "";

try {
  if (typeof responseText === 'string' && responseText.includes('{')) {
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsedData = JSON.parse(jsonMatch[0]);
    }
  } else if (typeof responseText === 'object' && responseText !== null) {
    parsedData = responseText;
  }
} catch (e) {}

// 3. חילוץ כמות וסכומים
const qty = Number(inputData.quantity || parsedData.quantity || triggerData.quantity || 0);
const totalPriceILS = Number(triggerData.totalPriceILS || triggerData.totalPriceList || inputData.totalPriceILS || 0);

// חישוב מחיר יחידה בדולר
let unitUSD = Number(inputData.unitCostUSD || parsedData.unitCostUSD || 0);
if (unitUSD === 0 && qty > 0 && totalPriceILS > 0) {
  unitUSD = Number((totalPriceILS / qty / 3.6).toFixed(2));
}

// חישוב סך הכל דולרי בטוח
let totalCostUSD = Number(inputData.totalCostUSD || parsedData.totalCostUSD || 0);
if (totalCostUSD === 0) {
  if (totalPriceILS > 0) {
    totalCostUSD = Number((totalPriceILS / 3.6).toFixed(2));
  } else if (qty > 0 && unitUSD > 0) {
    totalCostUSD = Number((qty * unitUSD).toFixed(2));
  }
}

// 4. אכיפת חוק ה-HITL (סף $30,000 או 108,000 ₪)
const requiresAuth = totalCostUSD > 30000 || totalPriceILS > 108000;
const finalDecision = requiresAuth ? 'REQUIRE_APPROVAL' : 'ORDER_NOW';

// 5. החזרת פלט דטרמיניסטי מתוקן
return [{
  json: {
    ...triggerData,
    ...inputData,
    ...parsedData,
    quantity: qty,
    unitCostUSD: unitUSD,
    totalCostUSD: totalCostUSD,
    authorizationRequired: requiresAuth,
    decision: finalDecision,
    status: 'PROCESSED_BY_PROCUREMENT'
  }
}];
